    ('act55side/level_act55side_02_beg.csv', 'line-625', '', 'Держать позиции! Ни шагу назад!'),
    ('act55side/level_act55side_02_beg.csv', 'line-626', '', 'Пусть это ужасное чудовище — но оно одно!'),
